def page_count(n_items, page_size):
    """Return how many pages are needed to show n_items, page_size to a page."""
    return n_items // page_size + (1 if n_items % page_size != 0 else 0)


def page(grades, number, page_size):
    """Return page `number` of grades. Pages are numbered from 1."""
    start = (number - 1) * page_size
    return grades[start:start + page_size]


def all_pages(grades, page_size):
    """Return every page of grades, in order."""
    return [page(grades, n, page_size) for n in range(1, page_count(len(grades), page_size) + 1)]
